// Verus program: longest maximum-length string with earliest tie-break
// The function returns None on empty input, otherwise Some(clone_of_input[i])
// where i is the smallest index among those achieving the maximum length.

use vstd::prelude::*;

verus! {

fn longest(strings: Vec<Vec<char>>) -> (result: Option<Vec<char>>)
    ensures
        // Empty input => None
        strings@.len() == 0 ==> result.is_None(),

        // Non-empty input => returns Some(s) with an index witness i
        strings@.len() > 0 ==> result.is_Some(),

        strings@.len() > 0 ==> (
            exists|i: int|
                0 <= i < strings@.len()
                && result.unwrap()@ == strings@[i]@
                // Max-length property
                && (forall|j: int| 0 <= j < strings@.len() ==> strings@[j]@.len() <= strings@[i]@.len())
                // Earliest among maxima (smallest index among max-length)
                && (forall|j: int| 0 <= j < i ==> strings@[j]@.len() < strings@[i]@.len())
        )
{
    if strings.len() == 0 {
        return None;
    }

    // We'll track the earliest index of the longest seen so far.
    let mut best_i: usize = 0;

    let mut k: usize = 1;
    while k < strings.len()
        invariant
            strings@.len() > 0,
            1 <= k <= strings@.len(),
            0 <= best_i < strings@.len(),
            best_i < k,

            // best_i is a max-length index among [0, k)
            forall|j: int| 0 <= j < k as int ==> strings@[j]@.len() <= strings@[best_i as int]@.len(),

            // best_i is the earliest index achieving that max among [0, k)
            forall|j: int| 0 <= j < best_i as int ==> strings@[j]@.len() < strings@[best_i as int]@.len(),
        decreases strings.len() - k
    {
        // Only update on strictly greater length; this preserves earliest tie-breaking.
        if strings[k].len() > strings[best_i].len() {
            best_i = k;
        }
        k = k + 1;
    }

    // Return a value exactly equal (by contents) to one of the inputs.
    Some(strings[best_i].clone())
}

} // verus!